const paths={terminal:'m4 6 5 6-5 6M12 18h8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',server:'M3 4h18v6H3zM3 14h18v6H3zM6 7h.01M6 17h.01M10 7h7M10 17h7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',folder:'M3 5h7l2 3h9v12H3z',file:'M5 3h9l5 5v13H5zM14 3v6h5',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',refresh:'M20 7V3l-4 4M20 7a8 8 0 1 0 0 10',more:'M5 12h.01M12 12h.01M19 12h.01',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',code:'m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sessions=[{name:'Refactor API',node:'dev-node-01',runtime:'Claude',path:'/workspace/cliora',status:'執行中',time:'剛剛'},{name:'Desktop UI exploration',node:'dev-node-02',runtime:'Codex',path:'/workspace/relvo-os',status:'執行中',time:'8 分鐘前'},{name:'Fix session reconnect',node:'dev-node-01',runtime:'Claude',path:'/workspace/cliora',status:'執行中',time:'24 分鐘前'},{name:'Release preparation',node:'build-node-01',runtime:'Shell',path:'/workspace/releases',status:'已結束',time:'昨天'}];
const nodes=[{name:'dev-node-01',os:'Ubuntu 24.04 LTS',cpu:24,mem:46,disk:38,online:true,count:2},{name:'dev-node-02',os:'Ubuntu 24.04 LTS',cpu:12,mem:32,disk:54,online:true,count:1},{name:'build-node-01',os:'Ubuntu 22.04 LTS',cpu:0,mem:0,disk:0,online:false,count:0}];
let theme='graphite';try{theme=localStorage.getItem('cliora-theme')||theme}catch{}const themes={graphite:'01 · 石墨專業',porcelain:'02 · 明亮極簡',midnight:'03 · 午夜藍',studio:'04 · 暖灰工作室',industrial:'05 · 工業終端'};if(!themes[theme])theme='graphite';
let view='workspace',tab='cli',current=0,filesOpen=innerWidth>800,focus=false,viewer=false,connected=true,selectedFile='client.ts',query='',runtime='all',history={cli:[],shell:[]};
const app=document.querySelector('#app'),dlg=document.querySelector('#dialog');
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',3500)}
function render(){document.body.className='theme-'+theme;const s=sessions[current];app.innerHTML=`<div class="app ${focus?'focus':''}"><aside class="sidebar"><div class="brand"><span class="logo">c</span><span>Cliora</span></div><p class="eyebrow">WORKSPACE</p>${[['workspace','terminal','工作台',''],['sessions','grid','Sessions',sessions.length],['nodes','server','Nodes','3'],['overview','grid','概況','']].map(([id,i,label,count])=>`<button class="nav ${view===id?'active':''}" data-view="${id}" title="${label}">${icon(i)}<span>${label}</span><small>${count}</small></button>`).join('')}<div class="saved"><p class="eyebrow">RECENT SESSIONS</p>${sessions.slice(0,3).map((s,i)=>`<button class="recent" data-open="${i}"><i class="dot ${i===2?'gray':''}"></i>${esc(s.name)}</button>`).join('')}</div><div class="sidebar-bottom"><button class="nav" data-action="about" title="原型說明">${icon('shield')}<span>原型說明</span></button><div class="profile"><div class="avatar">N</div><div>Neil<small>Personal workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')} <b>${({workspace:'Sessions',sessions:'所有 Sessions',nodes:'Nodes',overview:'概況'})[view]}</b>${view==='workspace'?`<span>/</span><span>${esc(s.name)}</span>`:''}</div><div class="top-tools"><span class="prototype">互動原型 · 模擬資料</span><select class="theme-select" id="theme" aria-label="視覺風格">${Object.entries(themes).map(([k,v])=>`<option value="${k}" ${theme===k?'selected':''}>${v}</option>`).join('')}</select></div></header><div class="content">${view==='workspace'?workspace():view==='sessions'?sessionPage():view==='nodes'?nodePage():overview()}</div><footer class="statusbar"><div class="statusgroup"><span><i class="dot ${connected?'':'amber'}"></i>${connected?'模擬連線正常':'重新連線中'}</span><span>${icon('shield')} ${viewer?'唯讀':'可操作'}</span></div><div class="statusgroup"><span>示範環境 · 不執行真實指令</span><span>Cliora / Visual Refresh</span></div></footer></main></div>`;bind()}
function workspace(){const s=sessions[current];return `<header class="workhead"><div><div class="titleline"><h1>${esc(s.name)}</h1><span class="tag live">${s.status}</span></div><div class="subline">${icon('server')}<span>${esc(s.node)}</span><span>·</span><span>${esc(s.runtime)}</span><span>·</span><code>${esc(s.path)}</code></div></div><div class="actions"><button class="btn" data-action="files">${icon('folder')}檔案</button><button class="btn" data-action="upload" ${viewer?'disabled':''}>${icon('upload')}投放圖片</button><button class="iconbtn" data-action="focus" aria-label="${focus?'離開聚焦模式':'聚焦模式'}" title="聚焦模式">${icon('expand')}</button><button class="iconbtn" data-action="controls" aria-label="Session 操作" title="Session 操作">${icon('more')}</button></div></header><div class="workbody ${filesOpen?'':'no-files'}"><section class="center"><div class="tabs" role="tablist">${[['cli','terminal','CLI'],['shell','code','系統終端'],['preview','file',selectedFile]].map(([id,i,label])=>`<button role="tab" aria-selected="${tab===id}" class="tab ${tab===id?'active':''}" data-tab="${id}">${icon(i)}${esc(label)}${id==='preview'?' <span class="tag">唯讀</span>':''}</button>`).join('')}<button class="iconbtn" data-action="reconnect" title="模擬重新連線" aria-label="模擬重新連線">${icon('refresh')}</button></div>${tab==='shell'?'<div class="shellwarn">系統終端 · 真實產品中可操作整台 Node，不受 workspace 路徑限制</div>':''}${tab==='preview'?`<div class="readonly">frontend/src/api/${esc(selectedFile)} · 唯讀預覽</div><div class="terminal"><pre class="preview-code">${esc(fileContent())}</pre></div>`:terminal()}<div class="term-note">${icon('terminal')}<span>${tab==='preview'?'檔案內容為示意資料':viewer?'目前為唯讀模式，可在右上角操作選單取得控制權':'模擬終端：可輸入 help、ls、pwd、git status、clear'}</span><span style="margin-left:auto"><kbd>Enter</kbd></span></div></section>${filesOpen?filePanel():''}</div>`}
function terminal(){const s=sessions[current];return `<div class="terminal" id="terminal"><div class="welcome"><span class="spark">✳</span><div><b>${tab==='shell'?'System terminal':esc(s.runtime)+' Code'}</b> <span class="dim"> / demonstration</span><div class="dim">${esc(s.path)}</div></div></div>${tab==='cli'?`<div class="dim">╭ Session restored · your workspace is ready</div><br><div><span class="green">❯</span> Review the API client and simplify error handling.</div><div class="termblock"><span class="green">●</span> Read <span class="blue">frontend/src/api/client.ts</span><br><span class="dim">&nbsp; 148 lines loaded</span><br><br><span class="green">●</span> Found the shared request handler.<br><span class="dim">&nbsp; The refresh flow already handles concurrent requests.</span></div><div>I’ll keep the existing authentication behavior and<br>focus on making the error responses consistent.</div><br><pre class="code"><span class="dim">  42</span> <span class="purple">async function</span> request&lt;T&gt;(path: string) {
<span class="dim">  43</span>   <span class="purple">const</span> response = <span class="purple">await</span> fetch(path);
<span class="dim">  44</span>   <span class="purple">if</span> (!response.ok) <span class="purple">throw</span> toApiError(response);
<span class="dim">  45</span>   <span class="purple">return</span> response.json() <span class="purple">as</span> Promise&lt;T&gt;;
<span class="dim">  46</span> }</pre>`:`<div class="dim">Ubuntu 24.04 LTS · ${esc(s.node)}</div><br><div class="green">Welcome to your node shell.</div>`}<div id="history">${history[tab].map(x=>`<div class="termblock"><div class="green">❯ ${esc(x.cmd)}</div><pre class="code">${esc(x.out)}</pre></div>`).join('')}</div><form class="term-command" id="command"><span class="green">❯</span><input autocomplete="off" aria-label="模擬終端指令" placeholder="${viewer?'唯讀模式':'輸入指令…'}" ${viewer||!connected||s.status==='已結束'?'disabled':''}></form></div>`}
function fileContent(){return selectedFile==='package.json'?'{\n  "name": "cliora-console",\n  "version": "0.1.0",\n  "private": true\n}':selectedFile==='README.md'?'# Cliora\n\nRemote development workbench.\n\n此為唯讀示範內容，未載入真實主機檔案。':`// ${selectedFile} — prototype preview\n\nimport { ref } from "vue";\n\nexport const connection = ref("connected");\n\nexport async function request<T>(path: string): Promise<T> {\n  const response = await fetch(path);\n  if (!response.ok) {\n    throw new Error(response.statusText);\n  }\n  return response.json();\n}\n\n// Existing remote session behavior remains unchanged.`}
function filePanel(){return `<aside class="files"><div class="filehead"><span>檔案總管</span><button class="iconbtn" data-action="files" title="收合檔案欄" aria-label="收合檔案欄">${icon('close')}</button></div><div class="folder-label">⌄ ${icon('folder')} cliora</div><details open><summary class="file">frontend</summary><details open><summary class="file indent">src</summary><details open><summary class="file deep">api</summary>${['client.ts','dto.ts'].map(f=>`<button class="file deep ${selectedFile===f?'active':''}" data-file="${f}"><span class="type">TS</span>${f}</button>`).join('')}</details>${['components','composables','views'].map(f=>`<details><summary class="file deep">${f}</summary><button class="file deep" data-file="${f==='views'?'SessionWorkspace.vue':f==='components'?'AppLayout.vue':'useTerminal.ts'}">${icon('file')}${f==='views'?'SessionWorkspace.vue':f==='components'?'AppLayout.vue':'useTerminal.ts'}</button></details>`).join('')}<button class="file deep" data-file="App.vue">${icon('code')}App.vue</button></details></details>${['package.json','README.md'].map(f=>`<button class="file" data-file="${f}">${icon('file')}${f}</button>`).join('')}<div class="filemeta">WORKSPACE<br><span style="color:var(--text)">${esc(sessions[current].path)}</span><br>唯讀預覽 · 示範檔案</div></aside>`}
function rows(){const filtered=sessions.map((s,i)=>({...s,i})).filter(s=>(s.name+' '+s.node+' '+s.path).toLowerCase().includes(query.toLowerCase())&&(runtime==='all'||s.runtime===runtime));return filtered.length?filtered.map(s=>`<tr><td><button class="textlink" data-open="${s.i}">${esc(s.name)}</button><small>${esc(s.path)}</small></td><td>${esc(s.node)}</td><td>${esc(s.runtime)}</td><td><span class="tag ${s.status==='執行中'?'live':''}">${s.status}</span></td><td>${s.time}</td><td><button class="iconbtn" data-open="${s.i}" aria-label="開啟 ${esc(s.name)}">${icon('chevron')}</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">沒有符合條件的 Session，請調整搜尋或篩選。</td></tr>'}
function sessionPage(){return `<div class="page"><div class="pagehead"><div><h1>所有 Sessions <span style="color:var(--muted);font-size:17px;margin-left:8px">${sessions.length}</span></h1><div class="description">跨節點的工作，從這裡繼續。</div></div><button class="btn primary" data-action="new">${icon('plus')}建立 Session</button></div><div class="filters"><input id="search" placeholder="搜尋名稱、節點或路徑" aria-label="搜尋 Sessions" value="${esc(query)}"><select id="runtime" aria-label="Runtime 篩選">${[['all','所有 Runtime'],['Claude','Claude'],['Codex','Codex'],['Shell','Shell']].map(([v,t])=>`<option value="${v}" ${runtime===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>SESSION / WORKSPACE</th><th>NODE</th><th>RUNTIME</th><th>狀態</th><th>最近活動</th><th></th></tr></thead><tbody id="rows">${rows()}</tbody></table></div></div>`}
function nodePage(){return `<div class="page"><div class="pagehead"><div><h1>Nodes</h1><div class="description">2 台線上 · 1 台離線</div></div><button class="btn" data-action="refresh">${icon('refresh')}重新整理</button></div><div class="nodegrid">${nodes.map((n,i)=>`<article class="card"><div class="cardtop">${icon('server')}<span class="tag ${n.online?'live':''}">${n.online?'線上':'離線'}</span></div><h2>${n.name}</h2><p>${n.os}</p><p>${n.count} 個執行中 Session</p>${['cpu','mem','disk'].map((m,j)=>`<div class="meter-row"><span>${['CPU','Memory','Storage'][j]}</span><span>${n.online?n[m]+'%':'無即時資料'}</span></div><div class="meter"><i style="width:${n[m]}%"></i></div>`).join('')}<button class="btn" data-node="${i}">查看節點 ${icon('chevron')}</button></article>`).join('')}</div><h2 class="section-title">執行環境</h2><div class="card"><span class="tag live">Claude 可用</span> <span class="tag live">Codex 可用</span><p>Runtime 可用性依各節點回報為準。此頁顯示示範資料。</p></div></div>`}
function overview(){return `<div class="page"><div class="pagehead"><div><p class="eyebrow" style="margin:0 0 10px">YOUR WORKSPACE</p><h1>晚上好，Neil</h1><div class="description">接續手上的工作。</div></div><button class="btn primary" data-action="new">${icon('plus')}建立 Session</button></div><div class="metrics">${[['線上節點','2 / 3','1 台節點離線'],['執行中 Sessions',sessions.filter(s=>s.status==='執行中').length,'跨 Claude 與 Codex'],['最近工作目錄','2','cliora · relvo-os']].map(([t,n,c])=>`<div class="card metric"><span style="color:var(--muted)">${t}</span><b>${n}</b><span style="color:var(--muted);font-size:12px">${c}</span></div>`).join('')}</div><h2 class="section-title">繼續工作</h2><div class="table-wrap"><table><tbody>${sessions.slice(0,3).map((s,i)=>`<tr><td>${icon('terminal')}</td><td><button class="textlink" data-open="${i}">${esc(s.name)}</button><small>${esc(s.path)}</small></td><td>${s.runtime}</td><td>${s.time}</td><td><button class="btn" data-open="${i}">開啟 ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div><h2 class="section-title">近期活動 <span class="tag">示範</span></h2>${[['23:42','Refactor API 已重新連線','dev-node-01'],['23:34','Desktop UI exploration 已建立','dev-node-02'],['22:58','build-node-01 離線','最後回報 44 分鐘前']].map(([t,a,n])=>`<div class="activity"><time>${t}</time><span>${a}</span><small>${n}</small></div>`).join('')}</div>`}
function openSession(i){current=Number(i);view='workspace';tab='cli';history={cli:[],shell:[]};render()}
function modal(html){dlg.innerHTML=html;dlg.showModal();dlg.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dlg.close())}
function bind(){app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openSession(b.dataset.open));app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});app.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{selectedFile=b.dataset.file;tab='preview';if(innerWidth<800)filesOpen=false;render()});document.querySelector('#theme').onchange=e=>{theme=e.target.value;try{localStorage.setItem('cliora-theme',theme)}catch{}render()};app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));app.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>nodeDetail(Number(b.dataset.node)));const form=document.querySelector('#command');if(form)form.onsubmit=e=>{e.preventDefault();const input=form.querySelector('input'),cmd=input.value.trim();if(!cmd)return;const s=sessions[current];if(cmd==='clear'){history[tab]=[];render();document.querySelector('#terminal').innerHTML='<div id="history"></div>'+form.outerHTML;bindCommandOnly();return}const out=cmd==='help'?'可用示範指令：help, ls, pwd, git status, clear\n其他指令不會在真實主機執行。':cmd==='ls'?'frontend/  backend/  daemon/  docs/  README.md':cmd==='pwd'?s.path:cmd==='git status'?'On branch visual-refresh\nYour branch is up to date.\nNothing to commit, working tree clean.':'此為前端模擬，不會執行真實指令。輸入 help 查看示範指令。';history[tab].push({cmd,out});render();const t=document.querySelector('#terminal');t.scrollTop=t.scrollHeight;document.querySelector('#command input').focus()};const search=document.querySelector('#search');if(search)search.oninput=e=>{query=e.target.value;updateRows()};const r=document.querySelector('#runtime');if(r)r.onchange=e=>{runtime=e.target.value;updateRows()}}
function bindCommandOnly(){bind()}
function updateRows(){document.querySelector('#rows').innerHTML=rows();document.querySelector('#rows').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openSession(b.dataset.open))}
function action(a){if(a==='files'){filesOpen=!filesOpen;render()}if(a==='focus'){focus=!focus;render()}if(a==='refresh')toast('示範資料已重新整理');if(a==='upload')document.querySelector('#upload').click();if(a==='about')modal('<h2>Cliora Visual Refresh</h2><p>這是可操作的前端視覺原型。所有主機、檔案及 CLI 回應皆為模擬，不會連接或修改真實環境。</p><p>可切換五種主題、開啟 Session、查看唯讀檔案，以及體驗連線與控制權狀態。</p><div class="actions"><button class="btn primary" data-close>開始探索</button></div>');if(a==='new')newSession();if(a==='reconnect'){connected=false;render();setTimeout(()=>{connected=true;render();toast('示範連線已恢復，Session 繼續執行')},1000)}if(a==='controls'){modal(`<h2>Session 操作</h2><p>${esc(sessions[current].name)} · 示範模式</p><div style="display:grid;gap:10px"><button class="btn" id="control">${viewer?'取得控制權':'切換為唯讀'}</button><button class="btn" id="reconnect">模擬重新連線</button><button class="btn danger" id="terminate" ${sessions[current].status==='已結束'?'disabled':''}>終止 Session…</button></div><div class="actions"><button class="btn" data-close>關閉</button></div>`);dlg.querySelector('#control').onclick=()=>{viewer=!viewer;dlg.close();render();toast(viewer?'已切換為唯讀模式':'已取得示範控制權')};dlg.querySelector('#reconnect').onclick=()=>{dlg.close();action('reconnect')};dlg.querySelector('#terminate').onclick=()=>{dlg.close();modal('<h2>終止此 Session？</h2><p>真實產品中，此操作會停止遠端 CLI 程序。此處只會變更示範資料。</p><div class="actions"><button class="btn" data-close>取消</button><button class="btn danger" id="confirm-stop">確認終止</button></div>');dlg.querySelector('#confirm-stop').onclick=()=>{sessions[current].status='已結束';dlg.close();render();toast('示範 Session 已結束')}}}}
function newSession(){modal(`<h2>建立 Session</h2><p>選擇執行環境，開始一段新的工作。</p><form id="new-session"><label>Session 名稱<input name="name" required maxlength="60" placeholder="例如：Review authentication flow"></label><label>Node<select name="node"><option>dev-node-01</option><option>dev-node-02</option></select></label><label>Runtime<select name="runtime"><option>Claude</option><option>Codex</option><option>Shell</option></select></label><label>Workspace<input name="path" required value="/workspace/cliora" pattern="/.*"></label><div class="actions"><button type="button" class="btn" data-close>取消</button><button class="btn primary" type="submit">建立並開啟</button></div></form>`);dlg.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const name=String(f.get('name')).trim();if(!name)return; sessions.push({name,node:f.get('node'),runtime:f.get('runtime'),path:f.get('path'),status:'執行中',time:'剛剛'});dlg.close();openSession(sessions.length-1);toast('已建立示範 Session，重新整理頁面會重設')};dlg.querySelector('input').focus()}
function nodeDetail(i){const n=nodes[i];modal(`<h2>${n.name}</h2><p>${n.os} · ${n.online?'線上':'離線'}</p><div class="card"><p>Runtime　${n.online?'Claude · Codex · Shell':'無即時資料'}</p><p>Workspace　/workspace</p><p>執行中 Session　${n.count}</p><p>執行姿態　一般使用者</p></div><div class="actions"><button class="btn" data-close>關閉</button>${n.online?'<button class="btn primary" id="node-new">建立 Session</button>':''}</div>`);const b=dlg.querySelector('#node-new');if(b)b.onclick=()=>{dlg.close();newSession();dlg.querySelector('[name=node]').value=n.name}}
document.querySelector('#upload').onchange=e=>{const f=e.target.files[0];if(f)toast(`已選取 ${f.name}（僅本機示範，未上傳）`);e.target.value=''};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focus){focus=false;render()}});render();
